customMethods.script:
rows = (BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.packOuts) or {}).get(method) or []
row = ([r for r in rows if r.get("PackOutId") == packOutId] or [None])[0]
if row is None:
	return
st = system.util.jsonDecode(BlueRidge.Common.Util.convertWrapperObjectToJson(self.view.custom.state)) or {}
block = BlueRidge.Parts.PackOutPopup.blockFromRow(self.view.params.value or 0, row)
sel = st.get("selected") or {}
draft = st.get("editDraft") or {}
sel[method] = block
draft[method] = dict(block)
self.view.custom.state = {"selected": sel, "editDraft": draft}

itemId = self.view.params.value or 0
if not itemId:
	BlueRidge.Common.Notify.toast("No item selected", "Select an item before saving container configuration.", "warning")
	return
res = BlueRidge.Parts.PackOutPopup.saveDraft(itemId, self.view.custom.state.editDraft, self.view.custom.state.selected, BlueRidge.Common.Session.currentAppUserId(self.session)) or {}
if res.get("Status"):
	BlueRidge.Common.Notify.toast("Container config saved", res.get("Message") or "", "success")
	self.load()
else:
	BlueRidge.Common.Notify.toast("Pack-out not saved", res.get("Message") or "Unknown error", "error")

# + New / Add: a blank named pack-out for this method in the form (unsaved).
st = system.util.jsonDecode(BlueRidge.Common.Util.convertWrapperObjectToJson(self.view.custom.state)) or {}
draft = st.get("editDraft") or {}
block = BlueRidge.Parts.PackOutPopup.blankBlock(self.view.params.value or 0, method)
block["Active"] = True
draft[method] = block
self.view.custom.state = {"selected": st.get("selected") or {}, "editDraft": draft}

pid = self.view.custom.state.editDraft[method]["PackOutId"]
res = BlueRidge.Parts.ContainerConfig.setDefault(pid, BlueRidge.Common.Session.currentAppUserId(self.session)) or {}
ok = bool(res.get("Status"))
BlueRidge.Common.Notify.toast("Default pack-out" if ok else "Default not changed", res.get("Message") or "", "success" if ok else "warning")
if ok:
	self.load()

pid = self.view.custom.state.editDraft[method]["PackOutId"]
res = BlueRidge.Parts.ContainerConfig.deprecate(pid, BlueRidge.Common.Session.currentAppUserId(self.session)) or {}
ok = bool(res.get("Status"))
BlueRidge.Common.Notify.toast("Pack-out removed" if ok else "Pack-out not removed", res.get("Message") or "", "success" if ok else "warning")
if ok:
	self.load()
